echo "=== tag balance check (awk) ==="
awk '
{
  # match self-closing tags like <rect ... />
  while (match($0, /<([a-zA-Z][a-zA-Z0-9]*)[^>]*\/>/)) {
    selfc++; $0 = substr($0, RSTART+RLENGTH)
  }
  # match opening tags
  while (match($0, /<([a-zA-Z][a-zA-Z0-9]*)((\"[^\"]*\"|[^>\"\/])*)>/)) {
    tag = substr($0, RSTART+1, RLENGTH-2)
    sub(/ .*/, "", tag)
    open[tag]++
    $0 = substr($0, RSTART+RLENGTH)
  }
  # match closing tags
  while (match($0, /<\/([a-zA-Z][a-zA-Z0-9]*)>/)) {
    tag = substr($0, RSTART+3, RLENGTH-4)
    close[tag]++
    $0 = substr($0, RSTART+RLENGTH)
  }
}
END {
